mapper.insert:
INSERT INTO cps_initial_review_task (
  issue_id, submission_id, version_no, status, review_task_ref, idempotency_key,
  submitted_at, timeout_at, retry_count, created_at, updated_at
) VALUES (
  #{issueId}, #{submissionId}, #{versionNo}, #{status}, #{reviewTaskRef}, #{idempotencyKey},
  #{submittedAt}, #{timeoutAt}, #{retryCount}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE cps_initial_review_task
SET review_task_ref = #{reviewTaskRef}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT t.id, t.issue_id, t.submission_id, t.version_no, t.status, t.review_task_ref, t.idempotency_key, t.submitted_at, t.timeout_at, t.completed_at, t.error_code, t.retry_count, t.taken_over_by, t.taken_over_name, t.taken_over_at, t.takeover_reason, i.status AS issue_status, r.overall AS result_overall, r.is_late AS result_is_late, a.decision AS adjudication_decision FROM cps_initial_review_task t LEFT JOIN cps_issue i ON i.id = t.issue_id LEFT JOIN cps_initial_review_result r ON r.task_id = t.id LEFT JOIN cps_review_adjudication a ON a.issue_id = t.issue_id AND a.version_no = t.version_no
t.status = #{status} AND t.issue_id = #{issueId}
ORDER BY t.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM cps_initial_review_task t

    t.status = #{status}
    AND t.issue_id = #{issueId}
